# common_compoundSurnames
common_compoundSurnames = ["欧阳","上官","皇甫","令狐","诸葛","司徒","司马","申屠","夏侯","贺兰","完颜","慕容","尉迟","长孙","鲜于", "闻人", "颛孙", "东方"]

def is_chinese_char(char):
    # Check if the Unicode code point of the character is within the range for Chinese characters
    return 0x4E00 <= ord(char) <= 0x9FFF

def convert_traditional_to_simplified(text):
    if pd.notna(text):  # Check if the value is not NaN
        new_text = HanziConv.toSimplified(text)
        if new_text:
            return new_text
        else:
            return text
    else:
        return text
        
def split_names(value):
        # files use ",", ";", "，" as delimiter for author names
        components = re.split(r'[;,，,1]\s*', value.replace(" ", ""))
        # components = value
        values = list()
        for component in components:
            # only accept chinese characters
            # only accept names without "·": only foreign names would contain this symbol
            if len(component) > 0 and is_chinese_char(component[0]) and (component.find("·") == -1):
                if component[:2] in common_compoundSurnames and len(component) > 2:#check double_Familynames
                    value = f"{component[:2]} {component[2:]}"
                    values.append(value)
                else:
                    if len(component[1:]) <= 2: #throw out suspecious foreign names: given name contains more than 2 characters
                        # only keep simplied chinese names
                        if convert_traditional_to_simplified(component) == component:
                            # Check each character in the common characters list
                            if all(char in characters for char in component):
                                value = f"{component[0]} {component[1:]}"
                                values.append(value)
        # return ';'.join(values) if values else pd.NA
        return values if values else pd.NA

def pinyinname(names):
    results = []
    for full_name in names:
        parts = full_name.split()
        surname = parts[0] # first part is surname
        givenname = parts[1]
        english_givenname = ''.join(
            # lookup_py_for_givenname.get(ch, ch) for ch in givenname
            lookup_py_for_givenname.get(ch, ch).split('#')[0] for ch in givenname #only take the first py
        )
        english_surname = lookup_py_for_surname.get(surname, lookup_py_for_compoundsurname.get(surname, surname))  # fallback to original if not found
        results.append(f"{english_surname} {english_givenname}".strip())
        
    return results
